package hu.boltseged.label;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import java.io.*; import java.nio.file.*; import java.util.*;
@Component public class LocalLabelStorage implements LabelStorage { private final Path root; public LocalLabelStorage(@Value("${app.labels.path}")String path){root=Path.of(path).toAbsolutePath().normalize();} public String put(UUID shipmentId,String fileName,String contentType,InputStream content)throws IOException{String key=shipmentId+"/"+UUID.randomUUID()+"-"+Path.of(fileName).getFileName();Path p=root.resolve(key).normalize();if(!p.startsWith(root))throw new IOException("Invalid label key");Files.createDirectories(p.getParent());Files.copy(content,p,StandardCopyOption.REPLACE_EXISTING);return key;}public InputStream get(String key)throws IOException{Path p=root.resolve(key).normalize();if(!p.startsWith(root))throw new FileNotFoundException();return Files.newInputStream(p);}}
